using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Product>(entity =>
        {
            entity.ToContainer("Products");

            // Preserve EF Core 8 discriminator property name (default changed to "$type" in EF Core 9)
            entity.HasDiscriminator<string>("Discriminator");

            // Preserve EF Core 8 compound id format "Product|123" (default changed to just "123" in EF Core 9)
            entity.HasRootDiscriminatorInJsonId(true);
        });

        // HasIndex removed — Cosmos DB indexing is managed via container indexing policy, not EF Core.
        // EF Core 9 throws at startup if HasIndex is used on a Cosmos entity.
    }
}
